package com.cyancoder.media.model;import jakarta.persistence.*;import java.time.Instant;@Entity@Table(name="media_reference",uniqueConstraints=@UniqueConstraint(name="uk_media_reference_owner",columnNames={"tenant_key","site_key","asset_key","owner_service","owner_type","owner_key","field_path"}),indexes=@Index(name="idx_media_reference_asset",columnList="tenant_key,site_key,asset_key"))public class MediaReferenceEntity{@Id@Column(name="reference_id",length=64)private String referenceId;@Column(name="tenant_key",nullable=false,length=200)private String tenantKey;@Column(name="site_key",length=200)private String siteKey;@Column(name="asset_key",nullable=false,length=64)private String assetKey;@Column(name="owner_service",nullable=false,length=100)private String ownerService;@Column(name="owner_type",nullable=false,length=100)private String ownerType;@Column(name="owner_key",nullable=false,length=200)private String ownerKey;@Column(name="field_path",nullable=false,length=300)private String fieldPath;@Column(name="created_at",nullable=false)private Instant createdAt;public String getReferenceId(){return referenceId;}public void setReferenceId(String v){referenceId=v;}public String getTenantKey(){return tenantKey;}public void setTenantKey(String v){tenantKey=v;}public String getSiteKey(){return siteKey;}public void setSiteKey(String v){siteKey=v;}public String getAssetKey(){return assetKey;}public void setAssetKey(String v){assetKey=v;}public String getOwnerService(){return ownerService;}public void setOwnerService(String v){ownerService=v;}public String getOwnerType(){return ownerType;}public void setOwnerType(String v){ownerType=v;}public String getOwnerKey(){return ownerKey;}public void setOwnerKey(String v){ownerKey=v;}public String getFieldPath(){return fieldPath;}public void setFieldPath(String v){fieldPath=v;}public Instant getCreatedAt(){return createdAt;}public void setCreatedAt(Instant v){createdAt=v;}}
